{
  "service": "gateway",
  "description": "gateway edge proxy",
  "listen": {
    "address": "127.0.0.1",
    "port": 8080
  },
  "tls": {
    "enabled": true,
    "verify_upstream": true,
    "min_version": "1.2"
  },
  "logging": {
    "level": "info",
    "format": "json",
    "sample_rate_pct": 100
  },
  "limits": {
    "max_body_kib": 512,
    "max_connections": 2048,
    "idle_timeout_s": 60
  },
  "features": {
    "compression": true,
    "http2": true,
    "request_ids": true
  },
  "upstreams": [
    {
      "name": "media",
      "host": "media.internal",
      "port": 9438,
      "weight": 3,
      "health_check": "/healthz"
    },
    {
      "name": "shipping",
      "host": "shipping.internal",
      "port": 9629,
      "weight": 7,
      "health_check": "/healthz"
    },
    {
      "name": "accounts",
      "host": "accounts.internal",
      "port": 8119,
      "weight": 3,
      "health_check": "/healthz"
    },
    {
      "name": "search",
      "host": "search.internal",
      "port": 9577,
      "weight": 10,
      "health_check": "/healthz"
    },
    {
      "name": "catalog",
      "host": "catalog.internal",
      "port": 9559,
      "weight": 7,
      "health_check": "/healthz"
    }
  ],
  "routes": [
    {
      "path": "/api/v1/media/history",
      "upstream": "media",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 2500,
      "retries": 0
    },
    {
      "path": "/api/v1/catalog/history",
      "upstream": "catalog",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 2000,
      "retries": 0
    },
    {
      "path": "/api/v1/media/labels",
      "upstream": "media",
      "methods": [
        "POST"
      ],
      "timeout_ms": 3000,
      "retries": 1
    },
    {
      "path": "/api/v1/shipping/lookup",
      "upstream": "shipping",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 1500,
      "retries": 2
    },
    {
      "path": "/api/v1/catalog/quotes",
      "upstream": "catalog",
      "methods": [
        "GET",
        "POST",
        "PATCH"
      ],
      "timeout_ms": 2000,
      "retries": 3
    },
    {
      "path": "/api/v1/media/batch",
      "upstream": "media",
      "methods": [
        "GET"
      ],
      "timeout_ms": 2500,
      "retries": 0
    },
    {
      "path": "/api/v1/shipping/tokens",
      "upstream": "shipping",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 1500,
      "retries": 1
    },
    {
      "path": "/api/v1/accounts/quotes",
      "upstream": "accounts",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 5000,
      "retries": 3
    },
    {
      "path": "/api/v1/search/status",
      "upstream": "search",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 5000,
      "retries": 1
    }
  ]
}

